package store
import("context";"os";"strconv";"strings";"sync";"testing";"time"
"github.com/apple1day/g3_health/backend/internal/config"
"github.com/apple1day/g3_health/backend/internal/snapshot"
"github.com/apple1day/g3_health/backend/internal/testutil")
func testDB(t *testing.T)*MySQL{t.Helper();if os.Getenv("MYSQL_INTEGRATION")!="1"{t.Skip("set MYSQL_INTEGRATION=1 against the isolated g3_health_ci database")};c:=config.Default();c.MySQL.DBName="g3_health_ci";c.MySQL.Prefix="test_"+strconv.FormatInt(time.Now().UnixNano(),10)+"_";c.MySQL.Password=os.Getenv("MYSQL_TEST_PASSWORD");if host:=os.Getenv("MYSQL_TEST_HOST");host!=""{c.MySQL.Path=host};if port:=os.Getenv("MYSQL_TEST_PORT");port!=""{c.MySQL.Port=port};c.Security=config.Security{UploadToken:strings.Repeat("u",43),ReadToken:strings.Repeat("r",43),AdminToken:strings.Repeat("a",43)}
 if e:=Migrate(context.Background(),c,false);e!=nil{t.Fatal(e)};s,e:=New(c);if e!=nil{t.Fatal(e)};t.Cleanup(func(){s.DB.Exec("DROP TABLE "+s.state);s.DB.Exec("DROP TABLE "+s.table);s.DB.Close()});return s}
func value(t *testing.T,when time.Time)snapshot.Snapshot{t.Helper();s,e:=snapshot.Parse(testutil.Raw(when),time.Now());if e!=nil{t.Fatal(e)};return s}
func TestMySQLHistoryRetryDailyAndDelete(t *testing.T){s:=testDB(t);ctx:=context.Background();base:=time.Now().UTC().Truncate(24*time.Hour).Add(-48*time.Hour+time.Hour);a:=value(t,base);receipt,e:=s.Put(ctx,a);if e!=nil{t.Fatal(e)};again,e:=s.Put(ctx,a);if e!=nil||!again.Equal(receipt){t.Fatal("retry was not idempotent",e)};b:=value(t,base.Add(time.Hour));s.Put(ctx,b);c:=value(t,base.Add(24*time.Hour));s.Put(ctx,c)
 if _,e=s.Put(ctx,a);e!=ErrConflict{t.Fatal("stale upload accepted")};changed:=c;x:=999.0;copyActivity:=*c.Activity;copyActivity.Steps=&x;changed.Activity=&copyActivity;if _,e=s.Put(ctx,changed);e!=ErrConflict{t.Fatal("same timestamp conflict accepted")}
 page,e:=s.List(ctx,Filter{Page:1,PageSize:2});if e!=nil||page.Total!=3||len(page.Items)!=2{t.Fatal("wrong history",e)};days,e:=s.Days(ctx,Filter{From:base.Format("2006-01-02"),To:base.Add(24*time.Hour).Format("2006-01-02")});if e!=nil||len(days)!=2||!days[0].Snapshot.GeneratedAt.Equal(b.GeneratedAt){t.Fatal("daily aggregation duplicated or summed",e)}
 r,e:=s.Latest(ctx);if e!=nil||!r.Snapshot.GeneratedAt.Equal(c.GeneratedAt){t.Fatal("latest mismatch")};if _,e=s.Get(ctx,r.ID);e!=nil{t.Fatal(e)}
 if e=s.DeleteAll(ctx);e!=nil{t.Fatal(e)};overview,e:=s.Overview(ctx);if e!=nil||overview.Count!=0||overview.Latest!=nil{t.Fatal("history not erased")};if e=s.DeleteAll(ctx);e!=nil{t.Fatal(e)}
}
func TestMySQLConcurrentUploadsKeepNewest(t *testing.T){s:=testDB(t);ctx:=context.Background();base:=time.Now().Add(-time.Hour);items:=make([]snapshot.Snapshot,12);for i:=range items{items[i]=value(t,base.Add(time.Duration(i)*time.Second))};var wg sync.WaitGroup;errs:=make(chan error,len(items));for _,v:=range items{wg.Add(1);go func(v snapshot.Snapshot){defer wg.Done();_,e:=s.Put(ctx,v);if e!=nil&&e!=ErrConflict{errs<-e}}(v)};wg.Wait();close(errs);for e:=range errs{t.Fatal(e)};last,e:=s.Latest(ctx);if e!=nil||!last.Snapshot.GeneratedAt.Equal(items[len(items)-1].GeneratedAt){t.Fatal("lost newest upload",e)}}
